// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Phishable} from "../src/Phishable.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Phishable c;

    function setUp() public {
        c = new Phishable(address(this));
    }

    function _run(address caller, address recipient) internal {
        bool reverted;
        try c.withdrawAll(recipient) { reverted = false; } catch { reverted = true; }
        assertTrue(reverted == (address(this) != c.owner()));
    }

    function testFuzz_run(address caller, address recipient) public {
        _run(caller, recipient);
    }

    receive() external payable { }
}
